class Solution:
    def circularPermutation(self, n: int, start: int) -> list[int]:
        return [start ^ (i ^ (i >> 1)) for i in range(1 << n)]

class Solution {
public:
    std::vector<int> circularPermutation(int n, int start) {
        int total = 1 << n;
        std::vector<int> res(total);
        for (int i = 0; i < total; ++i) {
            res[i] = start ^ (i ^ (i >> 1));
        }
        return res;
    }
};

class Solution {
    public java.util.List<Integer> circularPermutation(int n, int start) {
        int total = 1 << n;
        java.util.List<Integer> res = new java.util.ArrayList<>(total);
        for (int i = 0; i < total; i++) {
            res.add(start ^ (i ^ (i >> 1)));
        }
        return res;
    }
}

var circularPermutation = function(n, start) {
